template:
@php
    // The switch says where the place is; a block saved before it had a value reads the contacts, as new ones do.
    $fromSettings = $source !== 'coordinates';
    // What the component would refuse is not handed to it: a number off the earth is no number.
    $lat = is_numeric($latitude) && abs((float) $latitude) <= 90 ? (float) $latitude : null;
    $lng = is_numeric($longitude) && abs((float) $longitude) <= 180 ? (float) $longitude : null;
    $scale = is_numeric($zoom) ? max(1, min(19, (int) round((float) $zoom))) : 15;
    $tall = ['small' => '16em', 'medium' => '24em', 'large' => '32em'][$height] ?? '24em';
    $place = $address ? wx_text($address)->plain() : null;
    $contacts = $fromSettings ? \WebxUi\Widgets\Contacts\ContactsSource::get()?->primaryAddress() : null;
    $shown = $fromSettings ? $contacts !== null : $lat !== null && $lng !== null;
@endphp
@if ($shown)
<section class="b-map" data-wx-block="map">
    @if ($heading)
        <h2 class="b-map__heading">{{ $heading }}</h2>
    @endif
    @if ($fromSettings)
        <x-webx-map from="settings" :zoom="$scale" :height="$tall" />
    @else
        <x-webx-map :lat="$lat" :lng="$lng" :zoom="$scale" :height="$tall" :address="$place" />
    @endif
</section>
@endif
